#!/usr/bin/env python3
"""Turn 35 Wave 93: THE DOUBLE-TAP CLEAR, AND TWO DEVICE-TESTABLE GAPS NARROWED FROM THE WEB.

Wave 93's centrepieces:

1. DOUBLE-TAP CLEARING - a defensive control the corpus did not have at all. It is distinct
   from B (pressure) and from A (slide): as long as the system detects your defender is within
   range of the ball, he will **snap to it and kick it away instantly, with no possibility of
   causing a foul.** In a build where turning speeds are poor, that is a lifesaver - and it is
   strongest in box scrambles. Note the distinction the corpus must keep: double-tap CLEARING
   works, double-tap SHOOTING does not.

2. THE SECONDARY PRESS, with its failure mode named. The corpus knew it had been nerfed. This
   wave adds the two specific complaints: the second presser **freezes for a second** on winning
   the ball, giving the opponent time to take it back; and the press commits **only two players**
   while the rest disengage entirely. Plus the feature's version history - it was added/fixed in
   DLS25 (December 2024), where it won the ball about 80% of the time, and it was nerfed in DLS26.

3. THE OFFISDE TRAP, answered from the attacking side. The AI defenders DO attempt the line -
   and they do it **ineffectively**, which leaves the striker through on goal. That is a more
   useful answer than "it is missing", and it reframes the corpus's "never push defenders
   forward" rule: the problem is not that the trap is absent, it is that the trap is attempted
   badly by the AI.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w93')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_dc=new_ev("r/DreamLeagueSoccer 1qbjeuh '[Technical Discussion] The Meta of Double-Tap Clearing in Defense' (14 Jan 2026, from a self-described 10-year DLS veteran and former Tier 1 champion - the double-tap clear mechanic, its box-scramble use case, and the B-press immediacy downside), r/DreamLeagueSoccer 1pj67x3 'Dream League Soccer 2026 Community Review' (10 Dec 2025 - 'secondary pressing got nerfed', and 'CBs/defenders still try to play offside ineffectively when balls are played to the forwards which ends up meaning the striker is through on goal'), r/DreamLeagueSoccer 1pprkst (18 Dec 2025 - 'secondary press is still gone' and the re-implementation being 'much, much worse'), r/DreamLeagueSoccer 1pdr2g7 'My Dls 26 Gameplay Review' (4 Dec 2025 - 'secondary press is not working properly'), r/DreamLeagueSoccer 1pe0pja (4 Dec 2025 - 'the nonexistent secondary press'), r/DreamLeagueSoccer 1qbzi64 'How to defend in Dream League Live?' (13 Jan 2026 - 'Is the secondary pressing still working same as dls25. I am not able to use it properly as before'), r/DreamLeagueSoccer 1ke0jly (3 May 2025 - the second presser 'gets the ball and just stops moving for a second'), r/DreamLeagueSoccer 1ve8w1l 'DLS 2027 suggestions' (3 Aug 2026 - 'where are the offside traps, high lines, attacking shape' and 'defenders refuse to hold their line'; plus 'the secondary press is a decent feature but... the others aren't passively trying to get the ball'), r/DreamLeagueSoccer 1hh778r (18 Dec 2024 - 'secondary press is one of the most op tactics' with the exact input: 'hold down on an empty part of your display while defending and moving the active defender'), r/DreamLeagueSoccer 1lgu75k (21 Jun 2025 - 'You should get the ball like 80% of the time'), r/DreamLeagueSoccer 1h74h2a 'Things changed in DLS 25' (5 Dec 2024 - the secondary press being something players had been 'BEGGING for' and being fixed so defenders 'actually make tackles now'), r/DreamLeagueSoccer 1al1t8f (the double-tap shooting caveat), r/DreamLeagueSoccer 1pgcovy (7 Dec 2025 - the positive auto-switch view), r/DreamLeagueSoccer 1pial1k (9 Dec 2025 - 'the auto 2nd defender feature kinda sucks now'), sakibpro.com skill-moves page (12 May 2026 - the official Secondary Press description)",
    "THE DOUBLE-TAP CLEAR, THE SECONDARY PRESS'S FAILURE MODE, AND THE OFFISDE TRAP ANSWERED. (1) DOUBLE-TAP CLEARING, a defensive control the corpus did not have at all: 'I've recently discovered that **double-tap clearing is surprisingly powerful in DLS 26**. In a version where turning speeds are arguably disastrous, mastering this technique can be a lifesaver when standard tackling fails.' **The mechanism:** 'as long as the system detects your defender is within range of the ball, they will **snap to it and kick it away instantly, without any possibility of causing a foul.**' **The use case:** 'Box Scrambles - clearing the chaos inside the penalty area.' **The contrast with B:** 'When tackling from the side, the game often requires physical contact to complete before the ball is won. By then, the opponent might have already squeezed a shot off.' So double-tap skips the contact requirement entirely, which is why it beats B in traffic. **And the caveat the corpus must keep straight:** double-tap CLEARING works, but double-tap SHOOTING does not - 'The double tap shooting direction is always messed up.' (2) THE SECONDARY PRESS'S FAILURE MODE, named: 'they need to fix double press so that it actually works. Like for example sometimes when the player that is applying secondary pressure to the opponent, gets the ball and **just stops moving for a second**. That gives enough time for the opponent to get the ball back.' So the failure is not that the press misses - it is that the second presser FREEZES on ball-win and gives it back. (3) THE SECONDARY PRESS COMMITS ONLY TWO PLAYERS: 'my problem is let's say you're controlling those 2 players **the others aren't passively trying to get the ball just running away or not interested completely**.' So the press buys you two bodies and disengages the rest, which is a real tactical cost the corpus had not recorded. (4) THE FEATURE'S VERSION HISTORY: in DLS25 (December 2024) players had been 'BEGGING for' it and it was fixed so defenders 'actually make tackles now' - one thread called it 'one of the most op tactics' with a yield of '**like 80% of the time**', using the exact input 'hold down on an empty part of your display while defending and moving the active defender'. In DLS26 it was 'nerfed. Maybe a bit too much' - reported as 'still gone', 'not working properly', 'nonexistent', and 'not able to use it properly as before' as late as January 2026. One account says it was removed and re-implemented 'much, much worse'. (5) THE OFFISDE TRAP, ANSWERED FROM THE ATTACKING SIDE: 'What needs improving is that **CBs/defenders still try to play offside ineffectively when balls are played to the forwards which ends up meaning the striker is through on goal.**' So the AI DOES attempt the line - it just does it badly, and the cost of the failed attempt is a through ball. That is a more useful answer than 'it is missing', and it reframes the corpus's rule: the problem is not that the trap is absent, it is that it is attempted ineffectively by defenders you do not control. (6) C-029's Side B is CORROBORATED A SECOND TIME by a DLS26-dated source (August 2026): 'auto-switch is broken, **defenders refuse to hold their line**... Also, **where are the offside traps, high lines, attacking shape, and any kind of tactical transition when you lose possession?**' So the complaint persists eight months after launch, which strengthens the version-drift reading. (7) A SPLIT VERDICT ON AUTO-SWITCH, which the corpus should carry as a genuine disagreement rather than a single answer: 'The new auto-switch is way better. It doesn't just switch for you randomly anymore, you actually have to do it yourself, and because of that I feel like I control my players way more. My defending got better just from that alone' - against 'the auto switching is nonexistent... the defenders are lost and it doesn't even switch to the player closest to the ball.' (8) A DLS26 DEFENDING SENTIMENT: 'defending is way harder now, which makes the game fairer and makes you actually think instead of just mashing buttons' - so the nerfs are not universally unwelcome, and the corpus's defending rules are now aimed at a harder surface than DLS25's.",
    "DOUBLE-TAP CLEARING - a defensive control the corpus did not have: if your defender is in range of the ball, he SNAPS to it and kicks it away instantly, with no possibility of a foul. It is strongest in box scrambles, and it beats B because B requires physical contact before the ball is won. Keep it distinct from double-tap SHOOTING, which is unreliable. THE SECONDARY PRESS'S FAILURE MODE, named: the second presser FREEZES for a second on winning the ball, giving the opponent time to take it back - and the press commits only two players while the rest disengage. THE FEATURE'S HISTORY: added/fixed in DLS25 (Dec 2024) at about an 80% yield, nerfed in DLS26 and reported broken as late as January 2026. THE OFFISDE TRAP ANSWERED: the AI defenders DO attempt the line and do it INEFFECTIVELY, which leaves the striker through on goal - so the problem is not absence but a badly executed trap. C-029's Side B corroborated a second time. A genuine split verdict on auto-switch.",
    "THE DOUBLE-TAP CLEAR, AND TWO DEVICE-TESTABLE GAPS NARROWED",
    quality="community")

add_claim("DOUBLE-TAP CLEARING - a defensive control the corpus did not have at all: 'as long as the system detects your defender is within range of the ball, they will **snap to it and kick it away instantly, without any possibility of causing a foul.**' From a self-described 10-year veteran and former Tier 1 champion: 'double-tap clearing is surprisingly powerful in DLS 26. In a version where turning speeds are arguably disastrous, mastering this technique can be a lifesaver when standard tackling fails.'", 2, "gameplay/double-tap-clearing", [e_dc], notes="A third defensive control, distinct from B (pressure) and A (slide)")
add_claim("WHY DOUBLE-TAP CLEARING BEATS B, and where to use it: '**When tackling from the side, the game often requires physical contact to complete before the ball is won. By then, the opponent might have already squeezed a shot off.**' Double-tap skips the contact requirement entirely, so it is the tool for **box scrambles - 'clearing the chaos inside the penalty area.'**", 3, "gameplay/double-tap-clear-beats-b", [e_dc])
add_claim("KEEP THE TWO DOUBLE-TAPS STRAIGHT: double-tap **CLEARING** works and is foul-free; double-tap **SHOOTING** does not - 'The double tap shooting direction is always messed up.' So the mechanic is reliable defensively and unreliable offensively, and the corpus must not generalise from one to the other.", 3, "errata/double-tap-clear-vs-shoot", [e_dc], notes="Prevents a false generalisation in either direction")
add_claim("THE SECONDARY PRESS'S FAILURE MODE, named for the first time: 'they need to fix double press so that it actually works. Like for example sometimes when the player that is applying secondary pressure to the opponent, gets the ball and **just stops moving for a second**. That gives enough time for the opponent to get the ball back.' **So the failure is not that the press misses - it is that the second presser FREEZES on ball-win and gives it back.**", 3, "controls/secondary-press-freeze-failure-mode", [e_dc], notes="Turns a vague 'it is nerfed' into a specific, testable failure")
add_claim("THE SECONDARY PRESS COMMITS ONLY TWO PLAYERS: 'my problem is let's say you're controlling those 2 players **the others aren't passively trying to get the ball just running away or not interested completely.**' So the press buys you two bodies and disengages the rest - a real tactical cost the corpus had not recorded, and a reason not to lean on it as your primary defensive shape.", 3, "controls/secondary-press-two-players-only", [e_dc])
add_claim("THE SECONDARY PRESS'S VERSION HISTORY, which explains why the corpus's sources disagree: in **DLS25 (December 2024)** players had been 'BEGGING for' it and it was fixed so defenders 'actually make tackles now'; one thread called it '**one of the most op tactics**' with a yield of '**like 80% of the time**', using the input 'hold down on an empty part of your display while defending and moving the active defender'. In **DLS26** it was 'nerfed. Maybe a bit too much' - reported as 'still gone', 'not working properly', 'nonexistent', and 'not able to use it properly as before' as late as January 2026.", 3, "controls/secondary-press-version-history", [e_dc], notes="Explains the DLS25-vs-DLS26 disagreement across the corpus")
add_claim("THE SECONDARY PRESS WAS REMOVED AND RE-IMPLEMENTED BADLY, per one account: 'People complain about the new DLS 26 style of play so they brought back DLS 25 gamestyle' - 'They re-implemented the gameplay from the first DLS 26 update, but much, much worse.' So the current build may be a partial rollback rather than a clean nerf, which is why reports conflict.", 4, "controls/secondary-press-rollback", [e_dc])
add_claim("THE OFFISDE TRAP, ANSWERED FROM THE ATTACKING SIDE: 'What needs improving is that **CBs/defenders still try to play offside ineffectively when balls are played to the forwards which ends up meaning the striker is through on goal.**' So the AI DOES attempt the line - it just does it badly, and the cost of the failed attempt is a through ball. **That reframes the corpus's rule: the problem is not that the trap is absent, it is that it is attempted ineffectively by defenders you do not control.**", 3, "gameplay/offside-trap-attempted-ineffectively", [e_dc], notes="Substantially answers C-029 from the attacking side")
add_claim("C-029's Side B is CORROBORATED A SECOND TIME by a DLS26-dated source (August 2026): 'auto-switch is broken, **defenders refuse to hold their line**... Also, **where are the offside traps, high lines, attacking shape, and any kind of tactical transition when you lose possession?**' The complaint persists eight months after launch, which strengthens the version-drift reading over the one-off-bug reading.", 3, "errata/c-029-side-b-second-corroboration", [e_dc])
add_claim("A GENUINE SPLIT VERDICT ON AUTO-SWITCH, recorded as a disagreement rather than an answer: 'The new auto-switch is way better. It doesn't just switch for you randomly anymore, you actually have to do it yourself, and because of that I feel like I control my players way more. **My defending got better just from that alone**' - against 'the auto switching is nonexistent... the defenders are lost and it doesn't even switch to the player closest to the ball.' So the same change is a fix for one player and a breakage for another, and the corpus should not carry a single verdict.", 3, "controls/auto-switch-split-verdict", [e_dc])
add_claim("A DLS26 DEFENDING SENTIMENT worth carrying: 'defending is way harder now, which makes the game fairer and makes you actually think instead of just mashing buttons.' So the nerfs are not universally unwelcome - and the corpus's defending rules are now aimed at a harder surface than DLS25's, which is a reason to trust them more, not less.", 3, "gameplay/dls26-defending-harder-sentiment", [e_dc])
add_claim("THE EXACT SECONDARY-PRESS INPUT, restated because the corpus's descriptions vary: 'hold down on an **empty part of your display** while defending and moving the active defender' - the official description is 'Tap and hold in empty space when your opponent has the ball to press your opponent with another player', with the tip 'Release quickly to avoid leaving gaps in defense.'", 3, "controls/secondary-press-exact-input", [e_dc])
add_claim("A DLS25 BASELINE FOR THE SECONDARY PRESS, useful for a device test: 'Holding the screen while running towards an attacker brings another defender with you. **You should get the ball like 80% of the time** unless they do a skill move or pass before you reach them.' So a device test has a number to beat - if the press wins the ball materially less often than that, the nerf is real.", 3, "controls/secondary-press-80-percent-baseline", [e_dc], notes="Gives the device test a threshold rather than a yes/no")

for p in ['EV-506_double_tap_clear.html','EV-506b_secondary_press_and_offside.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
